import asyncio
import aiohttp
import html
import sys
from datetime import datetime
from typing import List, Dict, Tuple

async def fetch_url(session: aiohttp.ClientSession, url: str) -> Tuple[str, int, int, int]:
    start_time = datetime.now()
    try:
        async with session.get(url) as response:
            elapsed_ms = (datetime.now() - start_time).total_seconds() * 1000
            status_code = response.status
            content_length = response.content_length if response.content_length is not None else 0
            return url, status_code, content_length, int(elapsed_ms)
    except Exception:
        return url, "error", 0, int((datetime.now() - start_time).total_seconds() * 1000)

async def process_urls(input_file: str, output_file: str, max_concurrent: int = 4):
    async with aiohttp.ClientSession() as session:
        tasks = []
        with open(input_file, 'r') as f:
            urls = [line.strip() for line in f if line.strip()]
        for url in urls:
            task = asyncio.create_task(fetch_url(session, url))
            tasks.append(task)
            if len(tasks) >= max_concurrent:
                await asyncio.gather(*tasks)
                tasks = []

        if tasks:
            await asyncio.gather(*tasks)

    rows = []
    for task in asyncio.as_completed(tasks):
        url, status, content_length, elapsed = await task
        rows.append((url, status, content_length, elapsed))

    html_content = f"""<!DOCTYPE html>
<html>
<head>
    <title>Fetch Report</title>
    <style>
        table {{
            border-collapse: collapse;
            width: 100%;
        }}
        th, td {{
            border: 1px solid #dddddd;
            text-align: left;
            padding: 8px;
        }}
        th {{
            background-color: #f2f2f2;
        }}
    </style>
</head>
<body>
    <table>
        <tr>
            <th>URL</th>
            <th>Status</th>
            <th>Bytes</th>
            <th>Elapsed (ms)</th>
        </tr>
"""
    for url, status, content_length, elapsed in rows:
        html_content += f"""        <tr>
            <td>{html.escape(url)}</td>
            <td>{html.escape(str(status))}</td>
            <td>{content_length}</td>
            <td>{elapsed}</td>
        </tr>
"""
    html_content += """
    </table>
</body>
</html>
"""

    with open(output_file, 'w') as f:
        f.write(html_content)

def main():
    if len(sys.argv) != 3:
        print("Usage: python report.py INPUT OUTPUT")
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]

    asyncio.run(process_urls(input_file, output_file))

if __name__ == "__main__":
    main()
